insert into campsites (id, park_id, name, lat, lng, permit_required, site_type, description) values
  ('00000000-0000-4000-8000-000000003209', '00000000-0000-4000-8000-000000000005', 'Upper Tent Meadow (at-large)', 36.8369215, -118.586776, true, 'at-large', 'A high meadow about 5.5 miles up the Copper Creek Trail, above Lower Tent Meadow. Sloped, dispersed camping with no signage or bear box -- less used than the lower camp.'),
  ('00000000-0000-4000-8000-000000003210', '00000000-0000-4000-8000-000000000005', 'Granite Lake (at-large)', 36.8630685, -118.6201501, true, 'at-large', 'A subalpine lake in Granite Basin with views of Mount Hutchings, Goat Mountain, and Comb Spur. Dispersed camping at established impact sites; the final approach from the Copper Creek Trail is partly cross-country.');
