insert into parking_locations (id, park_id, trail_id, trailhead_name, lat, lng, address, permit_notes) values
  ('00000000-0000-4000-8000-000000003412', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003012', 'Copper Creek Trailhead', 36.7965, -118.5836, 'Copper Creek Trail, near Road''s End, Kings Canyon Scenic Byway (CA-180), Kings Canyon National Park, CA 93633', 'Same small trailhead lot as the Grouse Lake trip, near the Cedar Grove Pack Station; fills quickly given its limited size.');
insert into permits (id, park_id, trail_id, name, description, cost_usd, application_url, application_window, max_group_size, office_name, office_address, office_lat, office_lng) values
  ('00000000-0000-4000-8000-000000003506', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003012', 'Sequoia & Kings Canyon Wilderness Permit', 'Required for all overnight backcountry travel; Sequoia and Kings Canyon share one wilderness permit system. $15 per trip plus $5 per person during quota season. The Copper Creek entry point has a much smaller daily quota than the Rae Lakes Loop trailheads.', 15.00, 'https://www.recreation.gov/permits/445857', 'Quota season ~May 22-Sept 26. Reservations up to 6 months ahead, released daily at 7am PT.', 15, 'Road''s End Wilderness Permit Station', 'CA-180, Kings Canyon National Park, CA 93633 (end of Kings Canyon Scenic Byway, Cedar Grove)', 36.794682, -118.5826819);
insert into sights (id, park_id, trail_segment_id, name, description, photo_urls, photo_attribution, mile_marker) values
  ('00000000-0000-4000-8000-000000003131', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003121', 'Copper Creek Trail', 'A steep, switchbacking climb out of Cedar Grove with little shade, gaining nearly 3,600 ft on the way to Tent Meadow.', array['https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Copper_Creek_Trail.jpg/1280px-Copper_Creek_Trail.jpg'], 'Tom Hilton, CC BY 2.0, via Wikimedia Commons', 1.0),
  ('00000000-0000-4000-8000-000000003132', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003122', 'Granite Lake', 'A subalpine lake in Granite Basin at roughly 10,100 ft, ringed by Mount Hutchings, Goat Mountain, and Comb Spur.', array[]::text[], null, 4.0);
